MAP
  NAME "CONEXAO_OPENSEARCH"
  STATUS ON
  SIZE 800 600
  # acima do padrão de 4096, para o WCS entregar o bluemarble inteiro
  MAXSIZE 5400
  # filtros do WFS são recortados por este EXTENT: ele precisa cobrir todos os dados
  EXTENT -75 -35 -28 6
  UNITS DD
  SHAPEPATH "./data"
  IMAGECOLOR 255 255 255
  DEBUG 5

  WEB
    METADATA
      "wms_title"            "Meu Servidor de Mapas WMS"
      "wms_abstract"         "Serviço de mapas dinâmico rodando em Docker e FastCGI."
      "wms_onlineresource"   "http://localhost/mapserver?MAP=default&" # URL base do serviço
      "wms_srs"              "EPSG:4326 EPSG:3857 EPSG:4674"  # Projeções suportadas
      "wms_enable_request"   "*"                               # Permite GetCapabilities, GetMap, etc.

      "wfs_title"            "Meu Servidor de Feições WFS"
      "wfs_abstract"         "Serviço de feições rodando em Docker e FastCGI."
      "wfs_onlineresource"   "https://localhost/mapserver/ows?" # mesmo host de PUBLIC_HOST no .env; o nginx fixa o mapfile
      "wfs_srs"              "EPSG:4326 EPSG:3857 EPSG:4674"  # Projeções suportadas
      "wfs_enable_request"   "*"                               # Permite GetCapabilities, GetFeature, etc.

      "wcs_label"            "Meu Servidor de Coberturas WCS"
      "wcs_description"      "Serviço de coberturas rodando em Docker e FastCGI."
      "wcs_onlineresource"   "https://localhost/mapserver/ows?" # mesmo host de PUBLIC_HOST no .env
      "wcs_srs"              "EPSG:4326 EPSG:3857 EPSG:4674"  # Projeções suportadas
      "wcs_enable_request"   "*"                               # Permite GetCapabilities, GetCoverage, etc.
    END
  END

  OUTPUTFORMAT
    NAME "GEOTIFF"
    DRIVER "GDAL/GTiff"
    MIMETYPE "image/tiff"
    IMAGEMODE BYTE
    EXTENSION "tif"
  END

  PROJECTION
    "init=epsg:4326"
  END

  # -----------------------------------------------------------------
  # Camada conectada ao OpenSearch via OGR
  # -----------------------------------------------------------------
  LAYER
    NAME "poligonos_opensearch"
    TEMPLATE "empty" 

    METADATA
      "wms_title"         "OpenSearch teste"
      "wms_abstract"      "Camada de teste para acesso no OpenSearch"
      "wms_enable_request" "*"
      "wms_include_items"  "all"
      "wfs_title"          "OpenSearch teste"
      "wfs_abstract"       "Camada de teste para acesso no OpenSearch"
      "wfs_enable_request" "*"
      "gml_include_items"  "all"
      "gml_featureid"      "properties.fid"
      "gml_exclude_items"  "_id,id,type"
      "wms_exclude_items"  "_id,id,type"
      "gml_types"          "auto"
      # WFS lê gml_*, WMS lê wms_*
      "gml_properties.fid_alias" "fid"
      "wms_properties.fid_alias" "fid"
      "gml_properties.id_uni_estratigrafica_alias" "id_uni_estratigrafica"
      "wms_properties.id_uni_estratigrafica_alias" "id_uni_estratigrafica"
      "gml_properties.sigla_alias" "sigla"
      "wms_properties.sigla_alias" "sigla"
      "gml_properties.hierarquia_alias" "hierarquia"
      "wms_properties.hierarquia_alias" "hierarquia"
      "gml_properties.nome_alias" "nome"
      "wms_properties.nome_alias" "nome"
      "gml_properties.amb_tecto_alias" "amb_tecto"
      "wms_properties.amb_tecto_alias" "amb_tecto"
      "gml_properties.sub_amb_tectonico_alias" "sub_amb_tectonico"
      "wms_properties.sub_amb_tectonico_alias" "sub_amb_tectonico"
      "gml_properties.sigla_pai_alias" "sigla_pai"
      "wms_properties.sigla_pai_alias" "sigla_pai"
      "gml_properties.nome_pai_alias" "nome_pai"
      "wms_properties.nome_pai_alias" "nome_pai"
      "gml_properties.legenda_alias" "legenda"
      "wms_properties.legenda_alias" "legenda"
      "gml_properties.escala_alias" "escala"
      "wms_properties.escala_alias" "escala"
      "gml_properties.mapa_alias" "mapa"
      "wms_properties.mapa_alias" "mapa"
      "gml_properties.litotipos_alias" "litotipos"
      "wms_properties.litotipos_alias" "litotipos"
      "gml_properties.range_alias" "range"
      "wms_properties.range_alias" "range"
      "gml_properties.idade_min_alias" "idade_min"
      "wms_properties.idade_min_alias" "idade_min"
      "gml_properties.idade_max_alias" "idade_max"
      "wms_properties.idade_max_alias" "idade_max"
      "gml_properties.eon_min_alias" "eon_min"
      "wms_properties.eon_min_alias" "eon_min"
      "gml_properties.eon_max_alias" "eon_max"
      "wms_properties.eon_max_alias" "eon_max"
      "gml_properties.era_min_alias" "era_min"
      "wms_properties.era_min_alias" "era_min"
      "gml_properties.era_max_alias" "era_max"
      "wms_properties.era_max_alias" "era_max"
      "gml_properties.sistema_min_alias" "sistema_min"
      "wms_properties.sistema_min_alias" "sistema_min"
      "gml_properties.sistema_max_alias" "sistema_max"
      "wms_properties.sistema_max_alias" "sistema_max"
      "gml_properties.epoca_min_alias" "epoca_min"
      "wms_properties.epoca_min_alias" "epoca_min"
      "gml_properties.epoca_max_alias" "epoca_max"
      "wms_properties.epoca_max_alias" "epoca_max"
      "gml_properties.siglas_historicas_alias" "siglas_historicas"
      "wms_properties.siglas_historicas_alias" "siglas_historicas"
      "gml_properties.grupo_alias" "grupo"
      "wms_properties.grupo_alias" "grupo"
    END

    TYPE POLYGON
    STATUS ON
    
    # Define o tipo de conexão utilizando a biblioteca interna OGR
    CONNECTIONTYPE OGR
    
    # String de conexão apontando para o endpoint e índice do OpenSearch
    # Sintaxe: Elasticsearch:http://host:porta/nome_do_indice
    # CONNECTION "ES:http://opensearch-node1:9200"
    CONNECTION "ES:http://nginx:9200"   # O GDAL não suporta multiplas instâncias de OpenSearch
    
    # O GDAL não abre alias pelo nome: o curinga é proposital. Este padrão casa
    # com o alias litoestratigrafia_1m e não com os índices datados
    CONNECTIONOPTIONS
      "BATCH_SIZE" "2000"
      "LAYER" "litoestratigrafia*_1m"
    END
    
    # Caso seu OpenSearch exija autenticação, envie via cabeçalho HTTP:
    # OGR_HTTP_HEADERS "Authorization: Basic bXlfdXNlcjpteV9wYXNzd29yZA=="

    # Especifica qual campo/propriedade possui a geometria (ex: geo_point ou geo_shape)
    # DATA "litoestratigrafia_1m_20260728_192458"
    # Camada direta, sem SELECT: o MapServer anexa os filtros do WFS como WHERE ao
    # SQL, e o OGR não aceita ali os aliases do SELECT. Os campos properties.* são
    # renomeados pelos metadados *_alias da camada
    DATA "litoestratigrafia*_1m"

    

    PROJECTION
      "init=epsg:4326"
    END

    # Estilização visual para renderizar os pontos no mapa
    CLASS
      NAME "Areas do OpenSearch"
      STYLE
        COLOR 50 150 250               # Cor de preenchimento (Azul)
        OPACITY 60                     # Transparência do preenchimento (0-100)
        OUTLINECOLOR 0 0 150           # Cor da borda (Azul Escuro)
        WIDTH 1.5                      # Espessura da borda
      END
    END
  END

  # -----------------------------------------------------------------
  # Cobertura de exemplo para o WCS (mapserver/data fica fora do git)
  # -----------------------------------------------------------------
  LAYER
    NAME "bluemarble"
    TYPE RASTER
    STATUS ON
    DATA "bluemarble.tif"

    PROJECTION
      "init=epsg:4326"
    END

    METADATA
      "wcs_label"          "Blue Marble"
      "wcs_description"    "NASA Blue Marble com topografia e batimetria, janeiro de 2004"
      "wcs_enable_request" "*"
      "wcs_extent"         "-180 -90 180 90"
      "wcs_size"           "5400 2700"
      "wcs_resolution"     "0.0666666667 0.0666666667"
      "wcs_bandcount"      "3"
      "wcs_formats"        "GEOTIFF"
      "wcs_nativeformat"   "GEOTIFF"
      # o MapProxy pede o mapa inteiro: sem isto, a imagem entraria nos tiles
      "wms_enable_request" "!*"
      "wfs_enable_request" "!*"
    END
  END
END
